 if(job){const manual=store.get('manualReport:'+job.id,false);model.cost.begin('report:'+job.id,{kind:manual?'手动复盘':'自动复盘',background:!manual});store.set('manualReport:'+job.id,false);store.run("UPDATE jobs SET status='running' WHERE id=?",[job.id]);try{const reportInput=reportContext(job);if(!reportInput.groups.length)throw Error('所选日期或场次没有采集数据');const result=await model.run([{role:'system',content:PROMPT+'\n'+require('./business-analysis.cjs').skill().active.content+'\n当前软件模型配置：'+identity(model.config())+'\n'+RESPONSE_STYLE+'\n写一份运营复盘：采集覆盖、关键变化、投流判断、建议反馈、客户心理待验证假设、下一场方案。标注来源及不确定性。'},{role:'user',content:JSON.stringify(ContextBudget.reference(reportInput,'本场复盘 下一场动作'))}],{id:'report:'+job.id,direct:true});const ver=store.rows('SELECT MAX(version) AS v FROM reports WHERE kind=? AND scope=? AND day=?',[job.kind,job.scope,job.day])[0]?.v||0;store.run('INSERT INTO reports(kind,scope,day,at,content,status,version) VALUES(?,?,?,?,?,?,?)',[job.kind,job.scope,job.day,Date.now(),result.text,'已生成',ver+1]);store.run("UPDATE jobs SET status='done',error='' WHERE id=?",[job.id]);}catch(e){store.run("UPDATE jobs SET status='failed',error=?,attempt=attempt+1 WHERE id=?",[e.message,job.id]);}emit({type:'state'});return;}
